import {bodyHtml,readBodyEditor,bindBodyEditor} from './records-body.js';
import {chooseDraftExit} from './records-exit.js';
import './records.css';
import {inspectRecordFile} from './records-file-check.js';
import {directionStatuses,recordStatus,recordAttachments} from './records-model.js';
import {decorateActions} from './action-icons.js';
import {createRecordsStore} from './records-store.js';
import {canRecords,esc,day,localDateTime,dateTimeToISO,number,statusLabels,permissionLabels,validateDocument,invitationMail,code} from './records-model.js';
export function createRecordsModule(baseStore,logo){
 let api,root,lang='es',profile,boot=null,mode='documents',rows=[],parties=[],suppliers=[],adminData=null,doc=null,draft=null,dirty=false,busy=false,error='',notice='',q='',status='',offset=0,partyBack=false,adminTab='units',editing=null;
 let draftCount=0,exitPending=false,choosingSigner=false,pendingAttachments=[],memberSiteFilter='';
 let direction='incoming',filters={},filterCache={},filterPeople=[],intakeFile=null,intakePreview='',intakePages=0,intakeUploaded=false;
 const t=(es,en)=>lang==='es'?es:en,can=p=>canRecords(boot,p),b=(act,text,primary=false,attrs='')=>`<button type="button" class="${primary?'primary':'secondary'}" data-records="${act}" ${attrs}>${esc(text)}</button>`,opt=(value,text,selected)=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(text)}</option>`,labelStatus=s=>recordStatus(s,doc?.direction||direction,lang),fmt=v=>v?new Intl.DateTimeFormat(lang==='es'?'es-EC':'en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Pacific/Galapagos'}).format(new Date(v)):'—';
 const input=(name,label,value='',attrs='')=>`<label>${esc(label)}<input name="${name}" value="${esc(value)}" ${attrs}></label>`;
 const select=(name,label,html)=>`<label>${esc(label)}<select name="${name}">${html}</select></label>`;
 const blank=t('Seleccione','Select'),pick=()=>opt('',blank,''),statusBadge=s=>`<span class="badge ${['sent','signed','closed'].includes(s)?'green':'gray'}">${esc(labelStatus(s))}</span>`;
 function message(e){const m=String(e?.message||e);if(m.includes('DUPLICATE_ATTACHMENT'))return t('Ya hay un anexo con ese nombre. Revise los archivos o cambie el nombre antes de agregarlo.','An attachment with that name already exists. Review the files or rename it before adding.');if(m.includes('ENCRYPTED_PDF'))return t('El PDF está protegido. Suba una copia sin contraseña.','The PDF is encrypted. Upload a copy without a password.');if(m.includes('INVALID_PDF'))return t('No se pudo leer el PDF. Compruebe que esté completo y vuelva a exportarlo o escanearlo.','Unable to read the PDF. Check that it is complete and export or scan it again.');if(m.includes('REPLACEMENT_REASON'))return t('Indique el motivo para incorporar una nueva versión del oficio.','Enter a reason for adding a new version.');return m.includes('glf_records')&&(m.includes('find')||e?.code==='PGRST202')?t('El módulo necesita activar su migración de base de datos. Los demás módulos siguen disponibles.','This module requires its database migration. Other modules remain available.'):m.includes('MEMBER_REQUIRED')?t('Falta asignar su dirección, sede y cargo en Administración.','Assign your unit, site and job title in Administration first.'):m.includes('ORIGIN_CHANGED')?t('Cambió la dirección, sede o perfil de quien redactó. Devuelva el oficio para revisar y guardar su origen antes de aprobarlo.','The author’s unit, site or profile changed. Return the letter to review and save its origin before approval.'):m.includes('STALE')?t('El registro cambió. Vuelva a abrirlo antes de guardar.','The record changed. Reopen it before saving.'):m.includes('FORBIDDEN')?t('Su cuenta no tiene permiso para esta acción o el estado del oficio no la permite.','Your account or the letter state does not allow this action.'):m.includes('duplicate')||m.includes('DUPLICATE')?t('Ya existe ese nombre, sigla o combinación de iniciales. Revise el registro existente.','This name, code or initials combination already exists.'):m.includes('FILE')?t('Revise el archivo: PDF, o Word DOCX como original; máximo 20 MB.','Check the file: PDF, or Word DOCX as source; maximum 20 MB.'):t('No se pudo completar. Revise los datos, la conexión y los permisos.','Unable to complete. Check your data, connection and permissions.');}
 async function run(fn){if(busy)return;busy=true;error='';draw();try{await fn();return true;}catch(e){error=message(e);return false;}finally{busy=false;draw();}}
 async function refresh(){boot=await api.rpc('bootstrap');if(mode==='documents')filterPeople=await api.rpc('filter_people');if(mode==='admin')adminData=await api.rpc('admin');else if(mode==='documents'){const result=await api.rpc('list',null,null,{q,status,offset,direction,...filters});rows=result.rows;draftCount=result.draft_count||0;}else if(mode==='contacts'){parties=await api.rpc('parties',null,null,{q,offset});}else if(doc&&!draft)doc=await api.rpc('read',doc.id);}
 async function leave(){
  if(busy||exitPending)return false;if(!dirty)return true;
  if(mode!=='edit'||draft?.direction!=='outgoing')return confirm(t('Hay cambios sin guardar. ¿Desea salir?','There are unsaved changes. Leave?'));
  exitPending=true;const choice=await chooseDraftExit(lang);exitPending=false;
  if(choice==='stay')return false;
  if(choice==='save')return saveOutgoing();
  dirty=false;pendingAttachments=[];draft=null;mode=doc?'detail':'documents';return true;
 }
 async function saveOutgoing(){
  collect();if(!draft.document_date)draft.document_date=day();
  const errors=validateDocument(draft);if(errors.length){showErrors(root.querySelector('#record-editor'),errors);return false;}
  return run(async()=>{
   const data={...draft,recipients:draft.recipients.filter(r=>r.party_id)};
   const id=await api.rpc('save',draft.id||null,draft.version||null,data);
   draft.id=id;draft.version=(draft.version||0)+1;
   doc=await api.rpc('read',id);draft.version=doc.version;
   while(pendingAttachments.length){
    const file=pendingAttachments[0];
    if(!doc.files.some(f=>f.kind==='attachment'&&f.filename===file.name&&f.size===file.size)){
     notice=t('Subiendo anexo: ','Uploading attachment: ')+file.name;draw();
     await api.upload(doc,file,'attachment');doc=await api.rpc('read',id);draft.version=doc.version;
    }
    pendingAttachments.shift();draft.files=doc.files;
   }
   dirty=false;draft=null;choosingSigner=false;mode='detail';
   notice=t('Borrador guardado · ','Draft saved · ')+fmt(doc.updated_at)+t(' (Galápagos). Puede retomarlo en Oficios de salida → Borradores.',' (Galápagos). Resume it in Outgoing letters → Drafts.');
  });
 }
 window.addEventListener('beforeunload',ev=>{if(dirty&&root?.isConnected){ev.preventDefault();ev.returnValue='';}});
 function title(){return mode==='admin'?t('Direcciones, sedes y perfiles','Units, sites and roles'):t('Correspondencia y archivo','Correspondence and archive');}
 function draw(){if(!root)return;root.innerHTML=`<section class="module-heading"><div><h1>${title()}</h1><p>${mode==='admin'?t('Estructura organizacional y capacidades de las cuentas GLF existentes.','Organization and capabilities of existing GLF accounts.'):t('Oficios externos, seguimiento y archivo institucional.','External letters, tracking and institutional archive.')}</p></div>${mode!=='admin'?'<div class="actions">'+(direction==='outgoing'?b('new',t('Crear oficio','Create letter'),true,can('create')?'':'disabled'):b('incoming',t('Registrar oficio recibido','Register incoming letter'),true,can('receive')?'':'disabled title="'+t('Requiere permiso de recepción','Reception permission required')+'"'))+'</div>':''}</section><p class="error records-error" role="alert">${esc(error)}</p>${notice?`<p role="status" class="records-note">${esc(notice)}</p>`:''}${!boot?`<section class="panel">${error?b('retry',t('Reintentar','Retry')):t('Cargando…','Loading…')}</section>`:mode==='admin'?adminView():`<div class="records-tabs">${b('inbox',t('Oficios recibidos','Incoming letters'),direction==='incoming'&&mode!=='contacts',`aria-pressed="${direction==='incoming'&&mode!=='contacts'}"`)}${b('outbox',t('Oficios de salida','Outgoing letters'),direction==='outgoing'&&mode!=='contacts',`aria-pressed="${direction==='outgoing'&&mode!=='contacts'}"`)}${b('contacts',t('Instituciones y contactos','Institutions and contacts'),mode==='contacts')}</div>${mode==='edit'?editor():mode==='detail'?detail():mode==='party'?partyForm():mode==='contacts'?contactsView():listView()}`}`;
 if(busy){root.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=true);root.querySelector('[data-body-editor]')?.setAttribute('contenteditable','false');}
 bindBodyEditor(root,()=>{if(!busy){collect();dirty=true;}});
 root.querySelectorAll('[data-records]').forEach(el=>el.onclick=()=>act(el.dataset.records,el.dataset.id));
 root.querySelector('#records-search')?.addEventListener('submit',ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));q=f.q;status=f.status||'';filters=Object.fromEntries(['date_from','date_to','person_id','signer_id','deadline'].map(k=>[k,f[k]||'']));if(filters.date_from&&filters.date_to&&filters.date_from>filters.date_to){showErrors(ev.target,['date_to']);return;}offset=0;run(refresh);});
 root.querySelectorAll('#party-editor,#records-catalog,#records-member,#records-role').forEach(f=>f.addEventListener('input',()=>{dirty=true;}));
 const form=root.querySelector('#record-editor');if(form){form.oninput=ev=>{if(busy||ev.target.type==='file')return;collect();dirty=true;};form.onchange=ev=>{if(busy)return;collect();dirty=true;if(ev.target.name==='signer_id')choosingSigner=false;if((ev.target.name||'').startsWith('party_')||['no_external_number','signer_id'].includes(ev.target.name))draw();};form.onsubmit=ev=>{ev.preventDefault();if(draft.direction==='outgoing'){saveOutgoing();return;}collect();const errors=validateDocument(draft);if(errors.length){showErrors(form,errors);return;}if(draft.direction==='incoming'&&!intakeFile&&!draft.files?.some(f=>f.kind==='incoming')){showErrors(form,['intake_file']);return;}run(async()=>{const id=await api.rpc('save',draft.id||null,draft.version||null,draft);draft.id=id;doc=await api.rpc('read',id);draft.version=doc.version;if(draft.direction==='incoming'){if(intakeFile&&!intakeUploaded){notice=t('Cargando PDF…','Uploading PDF…');draw();await api.upload(doc,intakeFile,'incoming');intakeUploaded=true;doc=await api.rpc('read',id);draft.version=doc.version;}await api.rpc('register',doc.id,doc.version);doc=await api.rpc('read',id);}dirty=false;draft=null;clearIntake();mode='detail';notice=t('Registro completado.','Registration completed.');});};}
 root.querySelector('[name=annex_files]')?.addEventListener('change',async ev=>{
  ev.stopPropagation();const files=[...ev.target.files];if(!files.length)return;collect();
  await run(async()=>{const names=new Set([...(draft.files||[]).filter(f=>f.kind==='attachment').map(f=>f.filename),...pendingAttachments.map(f=>f.name)]);
   for(const file of files){if(names.has(file.name))throw Error('DUPLICATE_ATTACHMENT');names.add(file.name);await inspectRecordFile(file,'attachment');}
   pendingAttachments.push(...files);dirty=true;
  });
 });
 if(form?.querySelector('[name=no_external_number]')?.checked)form.querySelector('[name=external_number]').disabled=true;
 root.querySelector('[name=intake_file]')?.addEventListener('change',async ev=>{ev.stopPropagation();const file=ev.target.files[0];if(!file)return;collect();await run(async()=>{const meta=await inspectRecordFile(file,'incoming');clearIntake();intakeFile=file;intakePages=meta.pages;intakePreview=URL.createObjectURL(file);dirty=true;});});
 root.querySelector('#party-editor')?.addEventListener('submit',saveParty);
 root.querySelector('[name=kind]')?.addEventListener('change',()=>{if(mode==='party'){editing={...editing,...Object.fromEntries(new FormData(root.querySelector('#party-editor')))};draw();}});
 root.querySelector('#records-catalog')?.addEventListener('submit',saveCatalog);
 root.querySelector('#records-member')?.addEventListener('submit',saveMember);
 root.querySelector('[name=member_site_filter]')?.addEventListener('change',ev=>{memberSiteFilter=ev.target.value;root.querySelectorAll('[data-member-site]').forEach(row=>row.hidden=!!memberSiteFilter&&row.dataset.memberSite!==memberSiteFilter);});
 root.querySelector('#records-role')?.addEventListener('submit',saveRole);
 root.querySelector('[name=user_id]')?.addEventListener('change',ev=>{editing=adminData.members.find(m=>m.user_id===ev.target.value)||{user_id:ev.target.value,roles:[]};draw();});
 root.querySelector('#records-member')?.addEventListener('input',()=>{const f=new FormData(root.querySelector('#records-member'));root.querySelector('.records-code').textContent=code(boot.units.find(u=>u.id===f.get('unit_id'))?.code,boot.sites.find(s=>s.id===f.get('site_id'))?.code,f.get('initials'));});
 root.querySelectorAll('[data-upload]').forEach(el=>el.onchange=()=>{if(!el.files[0])return;const file=el.files[0],reason=root.querySelector('[name=replacement_reason]')?.value||'';run(async()=>{await api.upload(doc,file,el.dataset.upload,{reason});doc=await api.rpc('read',doc.id);notice=t('Archivo incorporado al oficio.','File added to the letter.');});});
 root.querySelector('#record-operation')?.addEventListener('submit',operation);
 decorateActions(root);
 }
 function listView(){const incoming=direction==='incoming',drafts=!incoming&&status==='draft';return `<section class="panel"><h2>${t(incoming?'Oficios recibidos':'Oficios de salida',incoming?'Incoming letters':'Outgoing letters')}</h2>${!incoming?'<div class="records-tabs">'+b('all-outgoing',t('Todos','All'),!drafts,`aria-pressed="${!drafts}"`)+b('drafts',t('Borradores','Drafts')+' ('+draftCount+')',drafts,`aria-pressed="${drafts}"`)+'</div>':''}<form id="records-search" class="records-toolbar">${input('q',t(incoming?'Buscar número GLF, número de origen, asunto o remitente':'Buscar número GLF, asunto o destinatario',incoming?'Search GLF number, source reference, subject or sender':'Search GLF number, subject or recipient'),q,'maxlength="200"')}${select('status',t('Estado','Status'),opt('',t('Todos','All'),status)+directionStatuses[direction].map(s=>opt(s,recordStatus(s,direction,lang),status)).join(''))}<button class="primary">${t('Buscar','Search')}</button>${b('clear',t('Limpiar filtros','Clear filters'))}<details class="records-wide records-filter-details"><summary>${t('Más filtros','More filters')}</summary><div class="form-grid">${input('date_from',t(incoming?'Recepción desde':'Fecha del oficio desde',incoming?'Received from':'Letter date from'),filters.date_from,'type="date"')}${input('date_to',t('Hasta','To'),filters.date_to,'type="date"')}${select('person_id',t(incoming?'Responsable':'Autor',incoming?'Owner':'Author'),opt('',t('Todos','All'),filters.person_id)+filterPeople.map(p=>opt(p.id,p.name,filters.person_id)).join(''))}${incoming?select('deadline',t('Plazo de atención','Deadline'),opt('',t('Todos','All'),filters.deadline)+opt('overdue',t('Vencido','Overdue'),filters.deadline)+opt('pending',t('En plazo','Within deadline'),filters.deadline)):select('signer_id',t('Firmante','Signer'),opt('',t('Todos','All'),filters.signer_id)+filterPeople.map(p=>opt(p.id,p.name,filters.signer_id)).join(''))}</div></details><p class="error records-error" role="alert"></p></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>${t('Número GLF','GLF number')}</th><th>${t('Asunto','Subject')}</th><th>${t(incoming?'Remitente':'Destinatario',incoming?'Sender':'Recipient')}</th><th>${t('Estado','Status')}</th>${drafts?'<th>'+t('Autor','Author')+'</th>':''}<th>${t(incoming?'Recepción':drafts?'Última modificación':'Fecha del oficio',incoming?'Received':drafts?'Last updated':'Letter date')}</th>${incoming?'<th>'+t('Responsable / plazo','Owner / deadline')+'</th>':''}<th></th></tr></thead><tbody>${rows.map(d=>`<tr><td><strong>${esc(number(d))}</strong>${incoming?'<small>'+t('Origen: ','Source: ')+esc(d.external_number||t('Sin número','No number'))+'</small>':''}</td><td>${esc(d.subject)}${d.classification==='restricted'?'<small>'+t('Restringido','Restricted')+'</small>':''}</td><td>${esc(d.correspondent||'—')}</td><td><span class="badge ${['sent','closed'].includes(d.status)?'green':'gray'}">${esc(recordStatus(d.status,d.direction,lang))}</span></td>${drafts?'<td>'+esc(d.author_name||'—')+'</td>':''}<td>${esc(incoming?fmt(d.received_at):drafts?fmt(d.updated_at):d.document_date)}</td>${incoming?'<td>'+esc(d.assigned_name||'—')+'<small>'+esc(d.due_date||'—')+'</small></td>':''}<td>${b(drafts&&d.author_id===profile.id&&can('create')?'resume':'open',drafts&&d.author_id===profile.id&&can('create')?t('Continuar edición','Continue editing'):t('Abrir','Open'),false,`data-id="${d.id}"`)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p class="records-empty">'+t('No hay oficios que coincidan con la consulta.','No matching letters.')+'</p>'}</div><div class="records-actions">${b('prev',t('Anterior','Previous'),false,offset?'':'disabled')}${b('next',t('Siguiente','Next'),false,rows.length===50?'':'disabled')}</div></section>`;}

 function contactsView(){return `<section class="panel"><form id="records-search" class="records-toolbar">${input('q',t('Buscar institución o contacto','Search institution or contact'),q,'maxlength="200"')}<button class="primary">${t('Buscar','Search')}</button>${b('party',t('Registrar institución o persona','Register institution or person'),false,can('contacts')?'':'disabled')}</form><p class="records-help">${t('Los proveedores existentes se vinculan desde su ficha; no se duplican sus datos comerciales.','Existing suppliers are linked; their commercial data is not duplicated.')}</p>${parties.map(p=>`<div class="records-file"><span><strong>${esc(p.name)}</strong><br>${esc(p.address)}<br>${esc(p.email||p.contacts?.[0]?.email||'')}</span>${b('contact-edit',t('Agregar contacto','Add contact'),false,`data-id="${p.id}" ${can('contacts')?'':'disabled'}`)}</div>`).join('')}<div class="records-actions">${b('prev',t('Anterior','Previous'),false,offset?'':'disabled')}${b('next',t('Siguiente','Next'),false,parties.length===50?'':'disabled')}</div></section>`;}
 function partyForm(){const p=editing||{};return `<form id="party-editor" class="panel"><h2>${t(p.id?'Agregar contacto':'Registrar contraparte',p.id?'Add contact':'Register correspondent')}</h2><div class="form-grid">${!p.id?select('supplier_id',t('Vincular proveedor existente (opcional)','Link existing supplier (optional)'),pick()+suppliers.map(s=>opt(s.id,`${s.legal_name} · ${s.id_number}`,p.supplier_id)).join('')):''}${select('kind',t('Tipo de persona','Person type'),opt('institution',t('Institución / persona jurídica','Institution / legal entity'),p.kind||'institution')+opt('natural',t('Persona natural','Individual'),p.kind))}${input('name',p.kind==='natural'?t('Nombres y apellidos','Full name'):t('Institución o razón social','Institution or legal name'),p.name,'maxlength="250"')}${input('address',t('Dirección','Address'),p.address,'maxlength="1000"')}${input('contact_name',p.kind==='natural'?t('Nombre del contacto (opcional)','Contact name (optional)'):t('Representante legal o máxima autoridad','Legal representative or highest authority'),'','maxlength="250"')}${input('job_title',t('Cargo','Job title'),'','maxlength="160"')}${input('email',t('Correo electrónico','Email'),'','type="email" maxlength="250"')}${input('phone',t('Teléfono','Phone'),'','type="tel" maxlength="40"')}</div><div class="records-actions"><button class="primary">${t('Guardar','Save')}</button>${b('party-cancel',t('Cancelar','Cancel'))}</div></form>`;}
 async function saveParty(ev){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));if(!f.supplier_id&&!editing?.supplier_id&&f.name.trim().length<2){showErrors(ev.target,['name']);return;}run(async()=>{const p=await api.rpc('party',editing?.id||null,editing?.version||null,{supplier_id:f.supplier_id||editing?.supplier_id||null,kind:f.kind,name:f.name,address:f.address,contact:[f.contact_name,f.job_title,f.email,f.phone].some(v=>v?.trim())?{name:f.contact_name,job_title:f.job_title,email:f.email,phone:f.phone,is_representative:f.kind==='institution'}:undefined});parties=await api.rpc('parties');if(!parties.some(x=>x.id===p.id))parties.unshift(p);editing=null;if(partyBack){const recipient={party_id:p.id,contact_id:p.contacts?.filter(c=>[c.name,c.job_title,c.email,c.phone].some(Boolean)).at(-1)?.id||null,kind:draft.direction==='incoming'?'from':'to'};const empty=draft.recipients.findIndex(r=>!r.party_id);if(empty>=0)draft.recipients[empty]=recipient;else draft.recipients.push(recipient);mode='edit';dirty=true;}else{mode='contacts';q='';dirty=false;}notice=t('Registro guardado.','Record saved.');});}
 function editor(){const d=draft;return `<form id="record-editor" class="panel" novalidate><h2>${t(d.direction==='incoming'?'Registrar oficio recibido':'Redactar oficio',d.direction==='incoming'?'Register incoming letter':'Draft letter')}</h2>${d.direction==='outgoing'?'<p class="records-help">'+t('Para guardar un borrador basta con indicar el asunto. Complete destinatario, contenido y firmante antes de remitirlo para firma.','Only a subject is needed to save a draft. Complete the recipient, content and signer before submitting for signature.')+'</p>':''}<p class="error records-error" id="record-errors" role="alert"></p><div class="form-grid">${input('subject',t('Asunto *','Subject *'),d.subject,'required minlength="3" maxlength="300"')}${d.direction==='incoming'?input('document_date',t('Fecha del oficio de origen *','Source letter date *'),d.document_date,`type="date" required max="${day()}"`):'<div class="records-auto"><strong>'+t('Fecha del oficio · automática','Letter date · automatic')+'</strong><span>'+esc(fmt(boot.server_time||new Date().toISOString()))+' (Galápagos)</span><small>'+t('Se actualiza al guardar y se fija al aprobar el oficio.','Updated on save and fixed when the letter is approved.')+'</small></div>'}${d.direction==='outgoing'?'':input('external_number',t('Número del oficio de origen','Source letter number'),d.external_number,'maxlength="160"')+`<label class="records-inline"><input type="checkbox" name="no_external_number" ${d.no_external_number?'checked':''}>${t('Sin número de origen','No source number')}</label>`}${select('classification',t('Visibilidad','Visibility'),opt('ordinary',t('Ordinario · consulta interna','Ordinary · internal access'),d.classification)+opt('restricted',t('Restringido · personas autorizadas','Restricted · authorized people'),d.classification))}${d.direction==='outgoing'?signerField(d):input('received_at',t('Fecha y hora de recepción · Galápagos *','Received date and time · Galápagos *'),d.received_at_local,`type="datetime-local" required max="${localDateTime()}"`)}${d.direction==='incoming'?select('channel',t('Canal de recepción','Received via'),[['email','Correo electrónico','Email'],['physical','Físico','Physical'],['portal','Portal','Portal'],['other','Otro','Other']].map(([v,es,en])=>opt(v,t(es,en),d.channel)).join(''))+input('physical_location',t('Ubicación del original físico (opcional)','Physical original location (optional)'),d.physical_location,'maxlength="1000"'):''}<div class="records-wide"><h3>${t(d.direction==='incoming'?'Remitente':'Destinatarios',d.direction==='incoming'?'Sender':'Recipients')}</h3><div class="records-toolbar">${input('party_search',t('Buscar institución o persona','Search institution or person'),'','maxlength="200"')}${b('search-parties',t(d.direction==='incoming'?'Buscar remitente':'Buscar destinatario',d.direction==='incoming'?'Search sender':'Search recipient'))}</div><div class="records-recipients">${d.recipients.map((r,i)=>`<div class="records-recipient">${select('party_'+i,t('Institución o persona','Institution or person'),pick()+parties.map(p=>opt(p.id,p.name,r.party_id)).join(''))}${select('contact_'+i,t('Contacto','Contact'),opt('',t('Contacto principal','Main contact'),r.contact_id)+ (parties.find(p=>p.id===r.party_id)?.contacts||[]).filter(c=>[c.name,c.job_title,c.email,c.phone].some(Boolean)).map(c=>opt(c.id,[c.name,c.job_title,c.email].filter(Boolean).join(' · '),r.contact_id)).join(''))}${d.direction==='outgoing'?select('kind_'+i,t('Destinatario','Recipient'),opt('to',t('Para','To'),r.kind)+opt('cc',t('Copia','Cc'),r.kind)):''}${b('remove-recipient',t('Quitar','Remove'),false,`data-id="${i}"`)}</div>`).join('')}</div><div class="records-actions">${b('add-recipient',t(d.direction==='incoming'?'Agregar remitente':'Agregar destinatario',d.direction==='incoming'?'Add sender':'Add recipient'))}${b('party-from-editor',t('Registrar o vincular contraparte','Register or link correspondent'),false,can('contacts')?'':'disabled')}</div></div><label class="records-wide">${t(d.direction==='incoming'?'Resumen / observaciones':'Contenido del oficio',d.direction==='incoming'?'Summary / notes':'Letter content')}${d.direction==='outgoing'?bodyEditor(d):`<textarea class="records-body" name="body" maxlength="60000">${esc(d.body)}</textarea>`}<small class="records-help">${d.direction==='incoming'?t('Registre observaciones sobre el documento recibido; el archivo original se conserva intacto.','Add notes about the incoming document; the original file is preserved.'):t('La plantilla añade saludo, despedida, firma y paginación. Puede adjuntar un Word de origen después de guardar; revise su contenido antes de preparar el PDF.','The template adds greeting, closing, signature and page numbers. You can attach a source Word after saving; review its content before preparing the PDF.')}</small></label>${d.direction==='incoming'?intakeFields():annexEditor(d)}</div><div class="records-actions"><button class="primary">${t(d.direction==='incoming'?'Registrar recepción':'Guardar borrador',d.direction==='incoming'?'Register reception':'Save draft')}</button>${b('cancel-edit',t('Cancelar','Cancel'))}</div></form>`;}
 function bodyEditor(d){return '<div class="records-format-toolbar" role="group" aria-label="'+t('Formato del contenido','Content formatting')+'">'+[['bold','',t('Negrita','Bold'),'B'],['justifyLeft','left',t('Alinear a la izquierda','Align left'),'≡'],['justifyCenter','center',t('Centrar','Center'),'≡'],['justifyFull','justify',t('Justificar','Justify'),'≡']].map(([command,align,label,icon])=>'<button type="button" class="secondary" data-body-command="'+command+'" data-align="'+align+'" aria-label="'+label+'" title="'+label+'" aria-pressed="false">'+(command==='bold'?'<strong>B</strong>':label)+'</button>').join('')+'</div><div class="records-body records-rich" data-body-editor contenteditable="true" role="textbox" aria-multiline="true" aria-label="'+t('Contenido del oficio','Letter content')+'">'+bodyHtml(d.body,d.body_format)+'</div><input type="hidden" name="body" value="'+esc(d.body||'')+'"><small class="records-help">'+t('Seleccione texto para aplicar negrita. La alineación se aplica al párrafo actual o a los párrafos seleccionados.','Select text to apply bold. Alignment applies to the current paragraph or selected paragraphs.')+'</small>';}
 function collect(){const form=root.querySelector('#record-editor');if(!form||!draft)return;const f=new FormData(form);for(const name of ['subject','document_date','place','classification','signer_id','external_number','channel','body','physical_location'])if(f.has(name))draft[name]=f.get(name);const rich=form.querySelector('[data-body-editor]');if(rich)Object.assign(draft,readBodyEditor(rich));draft.no_external_number=f.has('no_external_number');if(draft.no_external_number)draft.external_number='';if(f.has('received_at')){draft.received_at_local=f.get('received_at');try{draft.received_at=dateTimeToISO(draft.received_at_local);}catch{draft.received_at='';}}draft.recipients=draft.recipients.map((r,i)=>({party_id:f.get('party_'+i)||'',contact_id:f.get('contact_'+i)||null,kind:draft.direction==='incoming'?'from':f.get('kind_'+i)||'to'}));}
 function showErrors(form,names){form.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));for(const name of names){const el=form.querySelector(`[name="${name==='party_id'?'party_0':name}"]`);if(el)el.setAttribute('aria-invalid','true');if(name==='body')form.querySelector('[data-body-editor]')?.setAttribute('aria-invalid','true');}const p=form.querySelector('.records-error');if(p)p.textContent=t('Revise los campos resaltados antes de guardar.','Review the highlighted fields before saving.');else{error=t('Revise los datos obligatorios.','Review required fields.');}form.querySelector('[data-body-editor][aria-invalid],:not([type=hidden])[aria-invalid]')?.focus();}
 function detail(){const d=doc,isAuthor=d.author_id===profile.id,isSigner=d.signer_id===profile.id;return `<section class="panel"><div class="records-summary"><h2>${esc(number(d))} · ${esc(d.subject)}</h2>${statusBadge(d.status)}</div><p>${esc(d.origin_code)} · ${esc(d.author_name)} · ${esc(d.document_date)}${d.classification==='restricted'?' · '+t('Restringido','Restricted'):''}</p><div class="records-actions">${b('documents',t('Volver al listado','Back to list'))}${d.status==='draft'&&isAuthor?b('edit',t(d.direction==='incoming'?'Completar recepción':'Continuar edición',d.direction==='incoming'?'Complete reception':'Continue editing'))+(d.direction==='outgoing'?b('submit',t('Remitir para firma','Submit for signature'),true):''):''}${d.direction==='incoming'&&!d.internal_number&&d.status!=='draft'&&can('receive')?b('register',t('Asignar número de ingreso GLF','Assign GLF receipt number'),true):''}${d.status==='review'&&isSigner&&can('sign')?b('approve',t('Aprobar y preparar PDF','Approve and prepare PDF'),true)+b('return',t('Devolver con observaciones','Return with comments')):''}${d.direction==='outgoing'?b('pdf',t('Descargar PDF','Download PDF')):''}${d.direction==='incoming'&&can('assign')&&['received','assigned'].includes(d.status)?b('assign',t('Asignar responsable','Assign owner')):''}${d.direction==='incoming'&&d.status!=='draft'&&can('create')?b('reply',t('Preparar respuesta','Prepare response')):''}${['sent','received','assigned'].includes(d.status)&&can('archive')?b('close',t('Cerrar y archivar','Close and archive')):''}</div></section><div class="records-detail"><section class="panel"><h2>${t('Contenido','Content')}</h2>${d.recipients.filter(r=>d.direction!=='outgoing'||r.kind!=='cc').map(r=>`<p><strong>${esc(r.party?.name)}</strong><br>${esc(r.contact?.name||r.party?.representative||'')} ${esc(r.contact?.job_title||'')}</p>`).join('')}<div class="records-preview">${d.direction==='outgoing'?bodyHtml(d.body,d.body_format):esc(d.body)}</div><p><strong>${esc(d.signer_name||'')}</strong><br>${esc(d.job_title||'')}</p>${annexList(d)}${d.direction==='outgoing'&&d.recipients.some(r=>r.kind==='cc')?'<h3>'+t('Copia:','Cc:')+'</h3>'+d.recipients.filter(r=>r.kind==='cc').map(r=>`<p>${esc(r.contact?.name||r.party?.representative||'')}<br><strong>${esc(r.contact?.job_title||'')}</strong><br>${esc(r.party?.name||'')}</p>`).join(''):''}${d.direction==='incoming'?'<p>'+t('Número de origen: ','Source number: ')+esc(d.external_number||t('Sin número','No number'))+'</p><p>'+t('Recibido: ','Received: ')+fmt(d.received_at)+'</p>'+(d.physical_location?'<p>'+t('Original físico: ','Physical original: ')+esc(d.physical_location)+'</p>':''):''}${relatedView()}${operationView()}</section><section class="panel"><h2>${t('Documentos','Documents')}</h2>${d.files.map(f=>`<div class="records-file"><span>${esc(f.filename)}<small> · ${Math.ceil(f.size/1024)} KB</small></span>${b('download',t('Descargar','Download'),false,`data-id="${f.id}"`)}${f.mime==='application/vnd.openxmlformats-officedocument.wordprocessingml.document'&&d.status==='draft'&&isAuthor?b('word',t('Usar texto de Word','Use Word text'),false,`data-id="${f.id}"`):''}</div>`).join('')||`<p>${t('Sin archivos.','No files.')}</p>`}${d.direction==='outgoing'&&d.status==='draft'&&isAuthor?upload('source',t('Adjuntar Word de origen o PDF','Attach source Word or PDF'),'.docx,.pdf')+upload('attachment',t('Agregar anexo PDF','Add PDF attachment')):''}${d.direction==='incoming'&&can('receive')&&['received','assigned'].includes(d.status)?(d.files.some(f=>f.kind==='incoming')?input('replacement_reason',t('Motivo de la nueva versión *','Reason for new version *'),'','minlength="5" maxlength="3000"'):'')+upload('incoming',t(d.files.some(f=>f.kind==='incoming')?'Incorporar nueva versión PDF':'Incorporar oficio recibido PDF',d.files.some(f=>f.kind==='incoming')?'Add new PDF version':'Upload incoming letter PDF'))+upload('attachment',t('Agregar anexo PDF','Add PDF attachment')):''}${d.status==='prepared'&&isSigner&&can('sign')?upload('signed',t('Subir PDF firmado electrónicamente','Upload electronically signed PDF')):''}${d.status==='prepared'&&isSigner&&d.files.some(f=>f.kind==='signed')?b('verify',t('Registrar verificación de firma','Record signature verification'),true):''}${d.status==='signed'&&can('dispatch')?`<p class="records-help">${t('Prepare el correo para consultar la conexión institucional. Si no está disponible, puede enviar manualmente el PDF firmado y registrar su constancia.','Prepare the email to check the institutional connection. If unavailable, send the signed PDF manually and record its evidence.')}</p>${b('email',t('Preparar correo','Prepare email'),true)}${upload('proof',t('Subir constancia de envío PDF','Upload delivery evidence PDF'))}${b('manual_sent',t('Registrar envío realizado','Record completed delivery'))}`:''}${d.dispatches?.some(s=>['sending','uncertain'].includes(s.status))?`<p class="error" role="status">${t('El resultado del envío requiere comprobación. No repita el envío; verifique el buzón institucional antes de resolverlo.','Delivery requires verification. Do not resend; check the institutional mailbox before resolving it.')}</p>`:''}<h2>${t('Historial','History')}</h2>${d.events.map(e=>`<div class="records-event">${esc(eventLabel(e.action))}<small>${esc(e.actor_name)} · ${fmt(e.created_at)}</small>${e.detail?`<p>${esc(e.detail)}</p>`:''}</div>`).join('')}</section></div>`;}
 const upload=(kind,text,accept='.pdf')=>`<label class="records-help">${esc(text)}<input type="file" data-upload="${kind}" accept="${accept}"><small>${t('Máximo 20 MB por archivo.','Maximum 20 MB per file.')}</small></label>`;
 let op=null,mail={configured:false};
 function operationView(){if(!op)return '';const d=doc;return `<form id="record-operation" class="records-note"><h3>${esc(op.title)}</h3>${op.action==='assign'?select('assigned_to',t('Responsable','Owner'),pick()+(adminData?.users||boot.signers).map(u=>opt(u.id,u.name,d.assigned_to)).join(''))+input('due_date',t('Fecha límite (opcional)','Due date (optional)'),d.due_date||'','type="date"')+`<label><input type="checkbox" name="requires_response" ${d.requires_response?'checked':''}>${t('Requiere respuesta','Response required')}</label>`:''}${op.action==='verify'?`<p>${t('Verifique el PDF con su herramienta de firma. Compruebe firmante, integridad y contenido aprobado. Esta acción registra su revisión; no es una validación criptográfica automática.','Verify the PDF with your signature tool. Check the signer, integrity and approved content. This records your review; it is not automatic cryptographic validation.')}</p>${select('file_id',t('PDF revisado','Reviewed PDF'),d.files.filter(f=>f.kind==='signed').map(f=>opt(f.id,f.filename,'')).join(''))}`:''}${['email','manual_sent'].includes(op.action)?input('email',t('Destinatario','Recipient'),invitationMail(d,lang).to,'type="email" multiple required')+input('cc',t('Copia (opcional)','Cc (optional)'),invitationMail(d,lang).cc,'type="email" multiple')+ (op.action==='manual_sent'?select('proof_file_id',t('Constancia','Evidence'),pick()+d.files.filter(f=>f.kind==='proof').map(f=>opt(f.id,f.filename,'')).join('')):''):''}${op.action==='email'&&mail.configured?`<p>${t('Se enviará desde','Will be sent from')} ${esc(mail.from)}. ${t('Se adjuntarán el PDF firmado y los anexos del oficio.','The signed PDF and letter attachments will be included.')}</p>`:''}${op.action==='email'?input('subject',t('Asunto','Subject'),invitationMail(d,lang).subject)+`<label>${t('Mensaje','Message')}<textarea name="message" rows="7">${esc(invitationMail(d,lang).message)}</textarea></label>`:`<label>${t('Motivo / evidencia','Reason / evidence')}<textarea name="reason" required minlength="${['verify','manual_sent'].includes(op.action)?10:5}" maxlength="3000"></textarea></label>`}<div class="records-actions"><button class="primary">${op.action==='email'?(mail.configured?t('Enviar oficio','Send letter'):t('Copiar mensaje','Copy message')):t('Confirmar','Confirm')}</button>${b('cancel-operation',t('Cancelar','Cancel'))}</div></form>`;}
 async function operation(ev){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));if(op.action==='email'&&mail.configured){await run(async()=>{await api.send(doc,f);op=null;doc=await api.rpc('read',doc.id);notice=t('Gmail aceptó el envío. Esto no confirma lectura ni entrega al destinatario.','Gmail accepted the message. This does not confirm delivery or reading.');});return;}if(op.action==='email'){await navigator.clipboard.writeText(`${f.email}\n${f.cc?"Cc: "+f.cc+"\n":""}${f.subject}\n\n${f.message}`);notice=t('Mensaje copiado. No se ha enviado un correo. Adjunte el PDF firmado al enviarlo.','Message copied. No email was sent. Attach the signed PDF when sending.');op=null;draw();return;}run(async()=>{await api.rpc(op.action,doc.id,doc.version,{...f,requires_response:!!f.requires_response});op=null;doc=await api.rpc('read',doc.id);notice=t('Acción registrada.','Action recorded.');});}
 function eventLabel(a){return ({dispatch_prepared:t('Correo preparado','Email prepared'),dispatch_sent:t('Envío aceptado por Gmail','Email accepted by Gmail'),dispatch_failed:t('Envío rechazado','Email rejected'),dispatch_uncertain:t('Envío por verificar','Delivery to verify'),saved:t('Oficio guardado','Letter saved'),submit:t('Remitido para firma','Submitted for signature'),approve:t('Aprobado y numerado','Approved and numbered'),return:t('Devuelto con observaciones','Returned with comments'),confirm_upload:t('Archivo incorporado','File uploaded'),verify:t('Verificación de firma registrada','Signature review recorded'),manual_sent:t('Envío manual registrado','Manual dispatch recorded'),assign:t('Responsable asignado','Owner assigned'),close:t('Cerrado','Closed')})[a]||a;}
 function adminView(){if(!boot.admin)return `<section class="panel">${t('Requiere permiso de administración.','Administrator permission required.')}</section>`;if(!adminData)return '';const members=adminData.members||[],selected=editing||{};return `<div class="records-tabs">${[['units','Direcciones','Units'],['sites','Sedes','Sites'],['roles','Perfiles','Roles'],['members','Asignaciones','Assignments']].map(([key,es,en])=>b('admin-'+key,t(es,en),adminTab===key)).join('')}</div><section class="panel">${['units','sites'].includes(adminTab)?`<div class="table-wrap"><table><thead><tr><th>${t('Nombre','Name')}</th><th>${t('Sigla','Code')}</th><th>${t('Estado','Status')}</th><th></th></tr></thead><tbody>${boot[adminTab].map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.code)}</td><td>${t(x.active?'Activo':'Inactivo',x.active?'Active':'Inactive')}</td><td>${b('catalog-edit',t('Editar','Edit'),false,`data-id="${x.id}"`)}</td></tr>`).join('')}</tbody></table></div><form id="records-catalog"><h3>${t(selected.id?'Editar registro':'Agregar registro',selected.id?'Edit record':'Add record')}</h3><div class="form-grid">${input('name',t('Nombre *','Name *'),selected.name,'required minlength="2" maxlength="120"')}${input('code',t('Sigla *','Code *'),selected.code,`required pattern="[A-Z]{2,${adminTab==='sites'?6:10}}" ${selected.id?'readonly':''}`)}${selected.id?select('active',t('Estado','Status'),opt('true',t('Activo','Active'),String(selected.active))+opt('false',t('Inactivo','Inactive'),String(selected.active))):''}${input('reason',t('Motivo *','Reason *'),'','required minlength="5" maxlength="1000"')}</div><p class="records-help">${t('La sigla identifica una unidad de forma estable. Para reemplazarla, cree la nueva unidad y reasigne el personal; los oficios emitidos conservan su referencia.','Codes identify units permanently. To replace one, create the successor and reassign staff; issued letters retain their reference.')}</p><div class="records-actions"><button class="primary">${t('Guardar','Save')}</button>${b('admin-clear',t('Nuevo','New'))}</div></form>`:adminTab==='roles'?`<div class="records-actions">${adminData.roles.map(r=>b('role-edit',r.name,false,`data-id="${r.id}"`)).join('')}</div><form id="records-role"><h3>${t('Perfil de correspondencia','Correspondence role')}</h3>${input('name',t('Nombre *','Name *'),selected.name,'required minlength="2" maxlength="100"')}<div class="records-checks">${Object.entries(permissionLabels).map(([key,labels])=>`<label><input type="checkbox" name="permission" value="${key}" ${selected.permissions?.includes(key)?'checked':''}>${esc(labels[lang==='es'?0:1])}</label>`).join('')}</div>${input('reason',t('Motivo *','Reason *'),'','required minlength="5" maxlength="1000"')}<div class="records-actions"><button class="primary">${t('Guardar perfil','Save role')}</button>${b('admin-clear',t('Nuevo','New'))}</div></form>`:`<p class="records-help">${t('Seleccione una cuenta existente. Las altas y accesos a otras aplicaciones se conservan en Usuarios y accesos.','Select an existing account. Account provisioning and other application access remain in Users and access.')}</p><form id="records-member"><div class="form-grid">${select('user_id',t('Usuario *','User *'),pick()+adminData.users.filter(u=>u.active).map(u=>opt(u.id,u.name,selected.user_id)).join(''))}${select('unit_id',t('Dirección o área *','Unit *'),pick()+boot.units.filter(u=>u.active).map(u=>opt(u.id,u.name,selected.unit_id)).join(''))}${select('site_id',t('Sede de trabajo *','Work site *'),pick()+boot.sites.filter(s=>s.active).map(s=>opt(s.id,s.name,selected.site_id)).join(''))}${input('job_title',t('Cargo *','Job title *'),selected.job_title,'required minlength="2" maxlength="160"')}${input('initials',t('Iniciales *','Initials *'),selected.initials,'required pattern="[A-Z]{2,8}" maxlength="8"')}${input('reason',t('Motivo *','Reason *'),'','required minlength="5" maxlength="1000"')}</div><output class="records-code">${esc(code(boot.units.find(u=>u.id===selected.unit_id)?.code,boot.sites.find(s=>s.id===selected.site_id)?.code,selected.initials))}</output><div class="records-checks">${adminData.roles.map(r=>`<label><input type="checkbox" name="role" value="${r.id}" ${selected.roles?.includes(r.id)?'checked':''}>${esc(r.name)}</label>`).join('')}</div><p class="records-help">${t('Asignar una dirección no concede firma o recepción. Revise los perfiles seleccionados.','Assigning a unit does not grant signing or reception. Review selected roles.')}</p><button class="primary">${t('Guardar asignación','Save assignment')}</button></form><h3>${t('Usuarios por sede','Users by work site')}</h3>${select('member_site_filter',t('Filtrar usuarios por sede','Filter users by work site'),opt('',t('Todas las sedes','All sites'),memberSiteFilter)+boot.sites.map(s=>opt(s.id,s.name,memberSiteFilter)).join(''))}<div class="table-wrap"><table><thead><tr><th>${t('Usuario','User')}</th><th>${t('Dirección o área','Unit')}</th><th>${t('Sede de trabajo','Work site')}</th><th>${t('Cargo','Job title')}</th><th>${t('Siglas de origen','Origin code')}</th></tr></thead><tbody>${members.map(m=>`<tr data-member-site="${esc(m.site_id)}" ${memberSiteFilter&&memberSiteFilter!==m.site_id?'hidden':''}><td>${esc(adminData.users.find(u=>u.id===m.user_id)?.name)}</td><td>${esc(boot.units.find(u=>u.id===m.unit_id)?.name)}</td><td>${esc(boot.sites.find(s=>s.id===m.site_id)?.name)}</td><td>${esc(m.job_title)}</td><td>${esc(code(boot.units.find(u=>u.id===m.unit_id)?.code,boot.sites.find(s=>s.id===m.site_id)?.code,m.initials))}</td></tr>`).join('')}</tbody></table></div>`}</section>`;}
 async function saveCatalog(ev){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));run(async()=>{await api.rpc(adminTab==='units'?'unit':'site',editing?.id||null,editing?.version||null,{...f,active:f.active!=='false'});editing=null;dirty=false;await refresh();notice=t('Catálogo actualizado.','Catalog updated.');});}
 async function saveMember(ev){ev.preventDefault();const f=new FormData(ev.target),data={...Object.fromEntries(f),roles:f.getAll('role')};if(!data.user_id||!data.unit_id||!data.site_id){showErrors(ev.target,['user_id','unit_id','site_id']);return;}run(async()=>{await api.rpc('member',null,editing?.version||null,data);editing=null;dirty=false;await refresh();notice=t('Asignación guardada.','Assignment saved.');});}
 async function saveRole(ev){ev.preventDefault();const f=new FormData(ev.target);run(async()=>{await api.rpc('role',editing?.id||null,editing?.version||null,{name:f.get('name'),reason:f.get('reason'),permissions:f.getAll('permission')});editing=null;dirty=false;await refresh();notice=t('Perfil actualizado. Revise sus usuarios asignados.','Role updated. Review its assigned users.');});}
 async function act(action,id){if(busy)return;if(action==='change-signer'){collect();choosingSigner=!choosingSigner;draw();return;}if(action==='remove-pending-annex'){collect();pendingAttachments.splice(Number(id),1);dirty=true;draw();return;}if(action==='retry'){run(refresh);return;}if(action==='cancel-operation'){op=null;draw();return;}if(action.startsWith('admin-')){if(!await leave())return;dirty=false;adminTab=action==='admin-clear'?adminTab:action.slice(6);editing=null;draw();return;}if(action==='catalog-edit'){editing=boot[adminTab].find(x=>x.id===id);draw();return;}if(action==='role-edit'){editing=adminData.roles.find(x=>x.id===id);draw();return;}if(action==='remove-recipient'){collect();draft.recipients.splice(Number(id),1);dirty=true;draw();return;}if(action==='add-recipient'){collect();draft.recipients.push({party_id:'',kind:draft.direction==='incoming'?'from':'to'});dirty=true;draw();return;}
 if(action==='search-parties'){collect();const term=root.querySelector('[name=party_search]').value;const selected=parties.filter(p=>draft.recipients.some(r=>r.party_id===p.id));await run(async()=>{parties=await api.rpc('parties',null,null,{q:term});for(const p of selected)if(!parties.some(x=>x.id===p.id))parties.push(p);});return;}
 if(action==='contact-edit'){editing=parties.find(p=>p.id===id);partyBack=false;mode='party';draw();return;}
 if(action==='party-from-editor'){collect();partyBack=true;editing=null;mode='party';draw();return;}
 if(action==='party-cancel'){mode=partyBack?'edit':'contacts';editing=null;draw();return;}
 if(['assign','verify','return','close','email','manual_sent'].includes(action)){op={action,title:({assign:t('Asignar responsable','Assign owner'),verify:t('Verificación de firma','Signature verification'),return:t('Devolver con observaciones','Return with comments'),close:t('Cerrar oficio','Close letter'),email:t('Correo preparado','Prepared email'),manual_sent:t('Registrar envío realizado','Record completed delivery')})[action]};if(action==='assign')await run(async()=>{adminData={users:await api.rpc('assignees')};});else if(action==='email')await run(async()=>{mail=await api.mailStatus?.()||{configured:false};});else draw();return;}
 if(action==='word'){await run(async()=>{const file=doc.files.find(f=>f.id===id);const {extractWord}=await import('./records-word.js');const text=await extractWord(await api.download(file));draft={...structuredClone(doc),body:text,body_format:null,recipients:doc.recipients.map(r=>({party_id:r.party.id,contact_id:r.contact_id,kind:r.kind}))};parties=await api.rpc('parties');for(const r of doc.recipients)if(r.party&&!parties.some(p=>p.id===r.party.id))parties.push(r.party);mode='edit';dirty=true;notice=t('Texto importado. Revise y retire encabezados o firmas anteriores; la plantilla generará los nuevos. El Word original se conserva.','Text imported. Review and remove previous headers or signatures; the template will generate new ones. The original Word is retained.');});return;}if(action==='download'){const file=doc.files.find(f=>f.id===id);await run(async()=>download(await api.download(file),file.filename));return;}
 if(action==='pdf'){await run(async()=>{const {recordsPdf}=await import('./records-pdf.js');const snapshot=doc.revisions?.[0]?.snapshot||doc;const pdf=recordsPdf({...snapshot,attachments:snapshot.attachments||doc.files.filter(f=>f.kind==='attachment')},{logo,lang,draft:!doc.sequence});download(new Blob([pdf.buffer],{type:'application/pdf'}),pdf.filename);});return;}
 if(action==='submit'){const missing=validateDocument(doc,{submit:true});if(missing.length){error=t('Complete el destinatario, el contenido y el firmante antes de remitir para firma. Use Continuar edición.','Complete the recipient, content and signer before submitting. Choose Continue editing.');draw();return;}}
 if(['submit','approve','register'].includes(action)){await run(async()=>{await api.rpc(action,doc.id,doc.version);doc=await api.rpc('read',doc.id);notice=t('Estado actualizado.','Status updated.');});return;}
 if(!await leave())return;dirty=false;error='';notice='';op=null;
 await run(async()=>{
  if(action==='resume'){doc=await api.rpc('read',id);action='edit';}
  if(action==='open'){doc=await api.rpc('read',id);direction=doc.direction;draft=null;mode='detail';}
  else if(['new','incoming','reply','edit'].includes(action)){const incoming=action==='incoming';clearIntake();choosingSigner=false;pendingAttachments=[];if(action==='edit'){draft={...structuredClone(doc),recipients:doc.recipients.map(r=>({party_id:r.party.id,contact_id:r.contact_id,kind:r.kind}))};}else{draft={direction:incoming?'incoming':'outgoing',subject:action==='reply'?t('Respuesta: ','Reply: ')+doc.subject:'',document_date:day(),place:boot.sites.find(s=>s.id===boot.member?.site_id)?.name||'',body:'',classification:action==='reply'?doc.classification:'ordinary',signer_id:!incoming&&boot.signers.some(s=>s.id===profile.id)?profile.id:'',received_at_local:localDateTime(),received_at:new Date().toISOString(),channel:'email',parent_id:action==='reply'?doc.id:null,recipients:action==='reply'?doc.recipients.filter(r=>r.kind==='from').map(r=>({party_id:r.party.id,contact_id:r.contact_id,kind:'to'})):[{party_id:'',kind:incoming?'from':'to'}]};}parties=await api.rpc('parties');for(const r of doc?.recipients||[])if(r.party&&!parties.some(p=>p.id===r.party.id))parties.push(r.party);suppliers=await api.directory();direction=draft.direction;mode='edit';}
  else if(action==='party'){editing=null;partyBack=false;suppliers=await api.directory();mode='party';}
  else {if(['inbox','outbox'].includes(action)){if(mode!=='contacts')filterCache[direction]={q,status,offset,filters};direction=action==='inbox'?'incoming':'outgoing';({q='',status='',offset=0,filters={}}=filterCache[direction]||{});mode='documents';doc=null;}if(['documents','contacts'].includes(action)){mode=action;if(action==='documents')doc=null;}if(action==='cancel-edit')mode=doc?'detail':'documents';if(['drafts','all-outgoing'].includes(action)){direction='outgoing';mode='documents';doc=null;q='';status=action==='drafts'?'draft':'';filters={};offset=0;}if(action==='clear'){q='';status='';filters={};offset=0;}if(action==='next')offset+=50;else if(action==='prev')offset=Math.max(0,offset-50);else if(!['inbox','outbox'].includes(action))offset=0;draft=null;clearIntake();await refresh();}
 });
 }

 function signerField(d){const signer=boot.signers.find(s=>s.id===d.signer_id);return '<div class="records-auto records-signer"><strong>'+t('Persona que suscribe','Signatory')+'</strong><span>'+esc(signer?.name||t('Pendiente de asignar','Not assigned'))+(signer?.id===profile.id?' · '+t('Usted','You'):'')+'</span>'+(signer?.job_title?'<small>'+esc(signer.job_title)+'</small>':'')+(choosingSigner?select('signer_id',t('Seleccione la persona que suscribe','Select signatory'),opt('',t('Pendiente de asignar','Not assigned'),d.signer_id)+boot.signers.map(s=>opt(s.id,s.name,d.signer_id)).join('')):'<input type="hidden" name="signer_id" value="'+esc(d.signer_id||'')+'">')+b('change-signer',choosingSigner?t('Cerrar selección','Close selection'):signer?t('Cambiar persona que suscribe','Change signatory'):t('Asignar persona que suscribe','Assign signatory'))+(!signer?'<small>'+t('Puede guardar el borrador y asignar a una persona autorizada antes de remitirlo para firma.','Save the draft and assign an authorized signatory before submitting.')+'</small>':'')+'</div>';}
 function annexList(d){const files=recordAttachments(d);return files.length?'<section class="records-annex-list"><h3>'+t('Anexos','Attachments')+'</h3><ol>'+files.map(f=>'<li>'+esc(f.filename)+'</li>').join('')+'</ol></section>':'';}
 function annexEditor(d){return '<section class="records-wide records-intake"><h3>'+t('Anexos del oficio','Letter attachments')+'</h3><p class="records-help">'+t('Sus nombres se incorporan automáticamente después del nombre y cargo del firmante, en la vista previa y en el PDF.','Their names appear automatically after the signatory’s name and job title, in the preview and PDF.')+'</p>'+annexList(d)+'<label>'+t('Seleccionar anexos PDF','Select PDF attachments')+'<input type="file" name="annex_files" accept=".pdf,application/pdf" multiple></label><small class="records-help">'+t('Máximo 20 MB por archivo. Los archivos seleccionados se suben al guardar el borrador.','Maximum 20 MB per file. Selected files upload when the draft is saved.')+'</small>'+pendingAttachments.map((f,i)=>'<div class="records-file"><span>'+esc(f.name)+'<small>'+t('Pendiente de guardar','Pending save')+' · '+Math.ceil(f.size/1024)+' KB</small></span>'+b('remove-pending-annex',t('Quitar','Remove'),false,'data-id="'+i+'"')+'</div>').join('')+'</section>';}

 function clearIntake(){if(intakePreview)URL.revokeObjectURL(intakePreview);intakeFile=null;intakePreview='';intakePages=0;intakeUploaded=false;}
 function intakeFields(){return `<section class="records-wide records-intake"><h3>${t('Documento recibido','Received document')}</h3><label>${t('Oficio completo en PDF *','Complete letter as PDF *')}<input type="file" name="intake_file" accept=".pdf,application/pdf"></label><p class="records-help">${t('PDF · máximo 20 MB. Incluya todas las páginas, en orden y legibles.','PDF · maximum 20 MB. Include every page, in order and legible.')}</p><details><summary>ⓘ ${t('Recomendaciones de escaneo','Scanning recommendations')}</summary><p class="records-help">${t('Escanee a 200–300 ppp. Use escala de grises, o color si es necesario para distinguir sellos u otros elementos. El archivo debe abrir sin contraseña.','Scan at 200–300 dpi. Use grayscale, or color when needed to distinguish stamps or other elements. The file must open without a password.')}</p></details>${intakeFile?'<p>'+esc(intakeFile.name)+' · '+Math.ceil(intakeFile.size/1024)+' KB · '+intakePages+' '+t('página(s)','page(s)')+'</p><a class="button secondary" href="'+intakePreview+'" target="_blank" rel="noopener">'+t('Vista previa del PDF','Preview PDF')+'</a>':draft.files?.some(f=>f.kind==='incoming')?'<p>'+t('PDF ya incorporado. Puede completar la recepción.','PDF already uploaded. You can complete reception.')+'</p>':''}<p class="records-help">${t('El número GLF se asigna al completar el registro. Puede incorporar los anexos después.','The GLF number is assigned when registration is completed. Attachments can be added afterwards.')}</p></section>`;}
 function relatedView(){return doc.related?.length?'<h3>'+t('Correspondencia relacionada','Related correspondence')+'</h3>'+doc.related.map(r=>'<div class="records-related">'+b('open',number(r)+' · '+r.subject,false,'data-id="'+r.id+'"')+'<small>'+esc(recordStatus(r.status,r.direction,lang))+'</small></div>').join(''):'';}
 function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
 return {canLeave:leave,async mount(el,language,account,{admin=false}={}){root=el;lang=language;profile=account;if(admin)mode='admin';if(!api)api=await createRecordsStore(baseStore);await run(refresh);},reset(){clearIntake();pendingAttachments=[];choosingSigner=false;direction='incoming';filters={};filterCache={};boot=null;doc=null;draft=null;dirty=false;mode='documents';adminData=null;editing=null;}};
}
